// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources/{source}/account/userinfo", wrapper.GetSourceAccountUserinfo)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/artifact-analyses", wrapper.CreateArtifactAnalysis)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/artifact-analyses/{analysis_id}", wrapper.GetArtifactAnalysis)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/endpoints/search", wrapper.SearchEndpoints)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources/{source}/endpoints/{external_id}/response-actions", wrapper.ListResponseActions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/entities/lookup", wrapper.LookupEntity)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/events/search", wrapper.SearchEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/events/aggregate", wrapper.AggregateEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/context/resolve", wrapper.ResolveContext)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/evidence/exports", wrapper.CreateEvidenceExport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/evidence/exports/{export_id}", wrapper.GetEvidenceExport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/evidence/exports/{export_id}/content", wrapper.GetEvidenceContent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/findings/search", wrapper.SearchFindings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources/{source}/findings/{kind}/{external_id}", wrapper.GetFinding)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.Healthz)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/ping", wrapper.Ping)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions/search", wrapper.SearchSessions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources/{source}/sessions/{external_id}", wrapper.GetSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sources", wrapper.ListSources)

	return m
}
